278: # When a user interrupts a streaming response, ellmer's Chat is left in an
279: # inconsistent state. Normally, ellmer only adds turns to the Chat history after
280: # a stream completes successfully. When we interrupt mid-stream,
281: # we need to ensure that user/assistant turns alternate back-and-forth, and that
282: # all tool requests have matching tool results.
283: #
284: # For the purposes of this app, interrupts either occur 1) during the tool
285: # calling loop or 2) not.
286: # 1) When during the tool calling loop, just confirm that tool calling loops
287: # appear complete by patching requests that don't have matching results with
288: # a text content.
289: # 2) When not during tool calling, process the streamed text content and
290: # let that form the assistant turn.
291: patch_interrupted_chat <- function(
292:   client,
293:   streamed_content = NULL,
294:   user_input = NULL
295: ) {
296:   # saveRDS(
297:   #   list(client = client, streamed_content = streamed_content, user_input = user_input),
298:   #   "/Users/simoncouch/.config/side/before_patching.rds"
299:   # )
300:   request_ids <- character()
301:   for (turn in client$get_turns()) {
302:     .res <- lapply(turn@contents, function(c) {
303:       if (S7::S7_inherits(c, ellmer::ContentToolRequest)) {
304:         request_ids <<- c(request_ids, c@id)
305:       }
306:     })
307:   }
308: 
309:   result_ids <- character()
310:   for (turn in client$get_turns()) {
311:     .res <- lapply(turn@contents, function(c) {
312:       if (S7::S7_inherits(c, ellmer::ContentToolResult)) {
313:         result_ids <<- c(result_ids, c@request@id)
314:       }
315:     })
316:   }
317: 
318:   requests_without_matches <- request_ids[!request_ids %in% result_ids]
319: 
320:   old_turns <- client$get_turns()
321:   new_turns <- list()
322:   for (turn in old_turns) {
323:     turn@contents <- lapply(turn@contents, function(c) {
324:       if (
325:         S7::S7_inherits(c, ellmer::ContentToolRequest) &&
326:           c@id %in% requests_without_matches
327:       ) {
328:         return(ellmer::ContentText(
329:           paste0("_Tool call to `", c@name, "` interrupted._")
330:         ))
331:       }
332: 
333:       c
334:     })
335: 
336:     new_turns <- c(new_turns, turn)
337:   }
338: 
339:   # If there are requests without matches, the interruption happended during
340:   # the tool calling loop. In that case, just patch the tool call turns and
341:   # don't worry about updating from other streamed content--ellmer already
342:   # had a chance to form complete turns up to the penultimate one.
343:   if (length(requests_without_matches) > 0) {
344:     client$set_turns(new_turns)
345:     return(client)
346:   }
347: 
348:   if (!is.null(streamed_content)) {
349:     text_content <- vapply(
350:       streamed_content,
351:       function(c) S7::S7_inherits(c, ellmer::ContentText),
352:       logical(1)
353:     )
354:     text_content <- paste0(
355:       vapply(streamed_content[text_content], function(c) c@text, character(1)),
356:       collapse = ""
357:     )
358:     text_content <- paste0(text_content, "...\n\n_Streaming interrupted._")
359: 
360:     if (length(new_turns) == 0) {
361:       last_turn_is_assistant <- TRUE
362:     } else {
363:       last_turn_is_assistant <- new_turns[[length(new_turns)]]@role ==
364:         "assistant"
365:     }
366: 
367:     if (last_turn_is_assistant) {
368:       new_turns <- c(
369:         new_turns,
370:         list(
371:           ellmer::Turn("user", list(ellmer::ContentText(user_input))),
372:           ellmer::Turn("assistant", list(ellmer::ContentText(text_content)))
373:         )
374:       )
375:     } else {
376:       # The most recent turn is a user turn, so update its contents with
377:       # the new user input
378:       last_user_turn <- new_turns[[length(new_turns)]]
379:       last_user_turn@contents <- c(
380:         last_user_turn@contents,
381:         ellmer::ContentText(user_input)
382:       )
383:       new_turns[[length(new_turns)]] <- last_user_turn
384: 
385:       new_turns <- c(
386:         new_turns,
387:         list(ellmer::Turn("assistant", list(ellmer::ContentText(text_content))))
388:       )
389:     }
390:   }
391: 
392:   client$set_turns(new_turns)
393:   client
394: }
