321: # When a user interrupts a streaming response, ellmer's Chat is left in an
322: # inconsistent state. Normally, ellmer only adds turns to the Chat history after
323: # a stream completes successfully. When we interrupt mid-stream,
324: # we need to ensure that user/assistant turns alternate back-and-forth, and that
325: # all tool requests have matching tool results.
326: #
327: # For the purposes of this app, interrupts either occur 1) during the tool
328: # calling loop or 2) not.
329: # 1) When during the tool calling loop, just confirm that tool calling loops
330: # appear complete by patching requests that don't have matching results with
331: # a text content.
332: # 2) When not during tool calling, process the streamed text content and
333: # let that form the assistant turn.
334: patch_interrupted_chat <- function(
335:   client,
336:   streamed_content = NULL,
337:   user_input = NULL
338: ) {
339:   # saveRDS(
340:   #   list(client = client, streamed_content = streamed_content, user_input = user_input),
341:   #   "/Users/simoncouch/.config/side/before_patching.rds"
342:   # )
343:   request_ids <- character()
344:   for (turn in client$get_turns()) {
345:     .res <- lapply(turn@contents, function(c) {
346:       if (S7::S7_inherits(c, ellmer::ContentToolRequest)) {
347:         request_ids <<- c(request_ids, c@id)
348:       }
349:     })
350:   }
351: 
352:   result_ids <- character()
353:   for (turn in client$get_turns()) {
354:     .res <- lapply(turn@contents, function(c) {
355:       if (S7::S7_inherits(c, ellmer::ContentToolResult)) {
356:         result_ids <<- c(result_ids, c@request@id)
357:       }
358:     })
359:   }
360: 
361:   requests_without_matches <- request_ids[!request_ids %in% result_ids]
362: 
363:   old_turns <- client$get_turns()
364:   new_turns <- list()
365:   for (turn in old_turns) {
366:     turn@contents <- lapply(turn@contents, function(c) {
367:       if (
368:         S7::S7_inherits(c, ellmer::ContentToolRequest) &&
369:           c@id %in% requests_without_matches
370:       ) {
371:         return(ellmer::ContentText(
372:           paste0("_Tool call to `", c@name, "` interrupted._")
373:         ))
374:       }
375: 
376:       c
377:     })
378: 
379:     new_turns <- c(new_turns, turn)
380:   }
381: 
382:   # If there are requests without matches, the interruption happended during
383:   # the tool calling loop. In that case, just patch the tool call turns and
384:   # don't worry about updating from other streamed content--ellmer already
385:   # had a chance to form complete turns up to the penultimate one.
386:   if (length(requests_without_matches) > 0) {
387:     client$set_turns(new_turns)
388:     return(client)
389:   }
390: 
391:   if (!is.null(streamed_content)) {
392:     text_content <- vapply(
393:       streamed_content,
394:       function(c) S7::S7_inherits(c, ellmer::ContentText),
395:       logical(1)
396:     )
397:     text_content <- paste0(
398:       vapply(streamed_content[text_content], function(c) c@text, character(1)),
399:       collapse = ""
400:     )
401:     text_content <- paste0(text_content, "...\n\n_Streaming interrupted._")
402: 
403:     if (length(new_turns) == 0) {
404:       last_turn_is_assistant <- TRUE
405:     } else {
406:       last_turn_is_assistant <- new_turns[[length(new_turns)]]@role ==
407:         "assistant"
408:     }
409: 
410:     if (last_turn_is_assistant) {
411:       new_turns <- c(
412:         new_turns,
413:         list(
414:           ellmer::Turn("user", list(ellmer::ContentText(user_input))),
415:           ellmer::Turn("assistant", list(ellmer::ContentText(text_content)))
416:         )
417:       )
418:     } else {
419:       # The most recent turn is a user turn, so update its contents with
420:       # the new user input
421:       last_user_turn <- new_turns[[length(new_turns)]]
422:       last_user_turn@contents <- c(
423:         last_user_turn@contents,
424:         ellmer::ContentText(user_input)
425:       )
426:       new_turns[[length(new_turns)]] <- last_user_turn
427: 
428:       new_turns <- c(
429:         new_turns,
430:         list(ellmer::Turn("assistant", list(ellmer::ContentText(text_content))))
431:       )
432:     }
433:   }
434: 
435:   client$set_turns(new_turns)
436:   client
437: }
