# Remove YAML frontmatter and return content start line number
get_content_start <- function(skill_lines) {
  # skill_lines: character vector of lines from a markdown skill file

  if (length(skill_lines) == 0) return(1L)

  # Check if first line is --- (YAML frontmatter marker)
  if (skill_lines[1] != "---") return(1L)

  yaml_end_indices <- which(skill_lines == "---")

  if (length(yaml_end_indices) < 2L) {
    # Only one --- found or no valid YAML block, treat as no frontmatter
    return(1L)
  }

  # Second --- marks the end of the YAML frontmatter block
  # Content should start on the line after this second "---"
  content_start <- yaml_end_indices[2L] + 1L

  # Clamp to minimum 1 and maximum length+1 if past end
  if (content_start < 1L) content_start <- 1L
  if (content_start > length(skill_lines) + 1L) content_start <- length(skill_lines) + 1L

  return(as.integer(content_start))
}
