function (text) 
{
    truncate_text <- function(text, max_words = 4, max_chars = 40) {
        words <- strsplit(text, "\\s+")[[1]]
        result <- paste(head(words, max_words), collapse = " ")
        if (nchar(result) > max_chars) {
            paste0(substr(result, 1, max_chars - 3), "...")
        }
        else {
            result
        }
    }
    get_content_start <- function(skill_lines) {
        if (length(skill_lines) == 0) 
            return(1L)
        if (skill_lines[1] != "---") 
            return(1L)
        yaml_end_indices <- which(skill_lines == "---")
        if (length(yaml_end_indices) < 2L) {
            return(1L)
        }
        content_start <- yaml_end_indices[2L] + 1L
        if (content_start < 1L) 
            content_start <- 1L
        if (content_start > length(skill_lines) + 1L) 
            content_start <- length(skill_lines) + 1L
        return(as.integer(content_start))
    }
    sanitized <- paste(head(strsplit(text, "\\s+")[[1]], 4), 
        collapse = " ")
    sanitized <- gsub("[^a-z0-9]+", "_", tolower(sanitized))
    sanitized <- gsub("^_+|_+$", "", sanitized)
    paste0(sanitized, "__", format(Sys.time(), "%Y%m%d_%H%M%S"), 
        ".rds")
}
