remove_yaml_frontmatter <- function(skill_content) {
  # Returns content start line (1-based) after removing YAML frontmatter if present.
  # skill_content is a character vector of lines from readLines().
  # If the file does not start with "---" or only one "---" exists, returns 1.
  if (length(skill_content) == 0L || skill_content[1] != "---") {
    return(1L)
  }

  yaml_end <- which(skill_content == "---")
  # Frontmatter ends at the second "---" marker; start after that line.
  if (length(yaml_end) >= 2L) {
    return(yaml_end[2] + 1L)
  }

  # Only one "---" found (or YAML incomplete); keep default start.
  return(1L)
}

