```r
function (lines) 
{
    if (length(lines) == 0) {
        return(1L)
    }
    if (!identical(lines[1], "---")) {
        return(1L)
    }
    yaml_end_indices <- which(lines == "---")
    if (length(yaml_end_indices) < 2L) {
        return(1L)
    }
    content_start <- yaml_end_indices[2L] + 1L
    if (content_start < 1L) {
        content_start <- 1L
    }
    if (content_start > length(lines) + 1L) {
        content_start <- length(lines) + 1L
    }
    return(as.integer(content_start))
}
