256: # When a user interrupts a streaming response, ellmer's Chat is left in an
257: # inconsistent state. Normally, ellmer only adds turns to the Chat history after
258: # a stream completes successfully. When we interrupt mid-stream,
259: # we need to ensure that user/assistant turns alternate back-and-forth, and that
260: # all tool requests have matching tool results.
261: #
262: # For the purposes of this app, interrupts either occur 1) during the tool
263: # calling loop or 2) not.
264: # 1) When during the tool calling loop, just confirm that tool calling loops
265: # appear complete by patching requests that don't have matching results with
266: # a text content.
267: # 2) When not during tool calling, process the streamed text content and
268: # let that form the assistant turn.
269: patch_interrupted_chat <- function(
270:   client,
271:   streamed_content = NULL,
272:   user_input = NULL
273: ) {
274:   # saveRDS(
275:   #   list(client = client, streamed_content = streamed_content, user_input = user_input),
276:   #   "/Users/simoncouch/.config/side/before_patching.rds"
277:   # )
278:   request_ids <- character()
279:   for (turn in client$get_turns()) {
280:     .res <- lapply(turn@contents, function(c) {
281:       if (S7::S7_inherits(c, ellmer::ContentToolRequest)) {
282:         request_ids <<- c(request_ids, c@id)
283:       }
284:     })
285:   }
286: 
287:   result_ids <- character()
288:   for (turn in client$get_turns()) {
289:     .res <- lapply(turn@contents, function(c) {
290:       if (S7::S7_inherits(c, ellmer::ContentToolResult)) {
291:         result_ids <<- c(result_ids, c@request@id)
292:       }
293:     })
294:   }
295: 
296:   requests_without_matches <- request_ids[!request_ids %in% result_ids]
297: 
298:   old_turns <- client$get_turns()
299:   new_turns <- list()
300:   for (turn in old_turns) {
301:     turn@contents <- lapply(turn@contents, function(c) {
302:       if (
303:         S7::S7_inherits(c, ellmer::ContentToolRequest) &&
304:           c@id %in% requests_without_matches
305:       ) {
306:         return(ellmer::ContentText(
307:           paste0("_Tool call to `", c@name, "` interrupted._")
308:         ))
309:       }
310: 
311:       c
312:     })
313: 
314:     new_turns <- c(new_turns, turn)
315:   }
316: 
317:   # If there are requests without matches, the interruption happended during
318:   # the tool calling loop. In that case, just patch the tool call turns and
319:   # don't worry about updating from other streamed content--ellmer already
320:   # had a chance to form complete turns up to the penultimate one.
321:   if (length(requests_without_matches) > 0) {
322:     client$set_turns(new_turns)
323:     return(client)
324:   }
325: 
326:   if (!is.null(streamed_content)) {
327:     text_content <- vapply(
328:       streamed_content,
329:       function(c) S7::S7_inherits(c, ellmer::ContentText),
330:       logical(1)
331:     )
332:     text_content <- paste0(
333:       vapply(streamed_content[text_content], function(c) c@text, character(1)),
334:       collapse = ""
335:     )
336:     text_content <- paste0(text_content, "...\n\n_Streaming interrupted._")
337: 
338:     if (length(new_turns) == 0) {
339:       last_turn_is_assistant <- TRUE
340:     } else {
341:       last_turn_is_assistant <- new_turns[[length(new_turns)]]@role ==
342:         "assistant"
343:     }
344: 
345:     if (last_turn_is_assistant) {
346:       new_turns <- c(
347:         new_turns,
348:         list(
349:           ellmer::Turn("user", list(ellmer::ContentText(user_input))),
350:           ellmer::Turn("assistant", list(ellmer::ContentText(text_content)))
351:         )
352:       )
353:     } else {
354:       # The most recent turn is a user turn, so update its contents with
355:       # the new user input
356:       last_user_turn <- new_turns[[length(new_turns)]]
357:       last_user_turn@contents <- c(
358:         last_user_turn@contents,
359:         ellmer::ContentText(user_input)
360:       )
361:       new_turns[[length(new_turns)]] <- last_user_turn
362: 
363:       new_turns <- c(
364:         new_turns,
365:         list(ellmer::Turn("assistant", list(ellmer::ContentText(text_content))))
366:       )
367:     }
368:   }
369: 
370:   client$set_turns(new_turns)
371:   client
372: }
