get_content_start <- function(lines) {
  # Find start index after YAML frontmatter (1 = whole content if none)
  if (length(lines) == 0 || lines[1] != "---") {
    return(integer(1))
  }

  yaml_end <- which(lines == "---")
  if (length(yaml_end) < 2) {
    return(integer(1))
  }

  # Second --- marks end of YAML block; content starts after it
  return(yaml_end[2] + 1L)
}

