# Remove YAML frontmatter if present; returns minimal line index (1-based)
# after cutting off YAML between two "---" markers at top of file.
remove_yaml_frontmatter <- function(content) {
  # No YAML or doesn't start with marker -> keep whole content
  if (length(content) == 0 || content[1] != "---") {
    return(1)
  }

  yaml_ends <- which(content == "---")
  if (length(yaml_ends) < 2) {
    return(1)  # No closing marker found, keep whole content
  }

  # Start after the second "---" line (the closing marker)
  start <- yaml_ends[2] + 1

  # Ensure start does not exceed total lines; if it would be beyond,
  # return the default content start.
  if (start > length(content)) {
    return(1)
  }

  start
}

